  "claims": [
    {
      "claim": "Direct absolute/relative oral bioavailability measurements for structurally related beta-blockers all exceed the 20% threshold: pamatolol 64.9–103.5%, practolol 90–100%, pindolol 53–79.5%, diacetolol 30–43%, bufuralol 52–83%, and CP-331,684 27%.",
      "card_ids": ["C22","C23","C25","C14","C15","C17","C18","C24","C01","C13","C16","C20","C04","C07","C08","C10"]
    },
    {
      "claim": "L4 absorption evidence shows no solubility or permeability liability for the beta-blocker class: atenolol >1 mg/mL, acebutolol 4.08 mg/mL, propranolol high Caco-2 permeability ~3.4–3.7×10^-5 cm/s, and the closest urea-containing analog has water solubility 1.0 mg/mL.",
      "card_ids": ["C60","C55","C66","C62","C63","C58"]
    },
    {
      "claim": "L5 C78 shows celiprolol, a structurally similar aryloxypropanolamine urea, is subject to intestinal P-gp efflux; itraconazole increases its absorption. This is mechanistic evidence that rifampin (a P-gp inducer) could reduce absorption of the query, but it does not quantify F or establish F<20%.",
      "card_ids": ["C78"]
    },
    {
      "claim": "Other L5 records concern propranolol (high passive permeability, no efflux), atenolol (low permeability/paracellular), and salbutamol (no P-gp effect); they do not provide affirmative threshold-relevant low-F evidence for the query.",
      "card_ids": ["C67","C69","C71","C73","C77","C70","C75","C68"]
    },
    {
      "claim": "L3 exposure reductions for nadolol with EGCG and albuterol with food involve different molecules and co-treatments and do not establish F below 20%.",
      "card_ids": ["C46","C44","C49","C54"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C78","C70","C75","C67","C77","C68"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query under rifampin or at baseline.",
    "No rifampin co-treatment PK data in any supplied record.",
    "No query-specific P-gp efflux or intestinal metabolism measurement; C78 is celiprolol, not the query.",
    "Baseline F of the query is unknown; transfer from beta-blocker analogs is indirect.",
    "L5 records do not provide numeric F or threshold-relevant low outcome."
  ],
  "decision_summary": "Predicted high because all transferable direct F records for structurally related beta-blockers exceed 20% and L4 absorption evidence supports adequate solubility/permeability; L5 adds a mechanistic P-gp efflux concern for the celiprolol-like urea core (C78) that could be relevant under rifampin, but it does not affirmatively establish F<20%, so the high prediction is kept with moderate confidence."
}

